  zrl_mi.add_scroll_event = function() {
    var iframe;
    iframe = document.getElementById('zrl_iframe');
    if (iframe) {
      if (!zrl_mi.is_mobile) {
        iframe.addEventListener('mouseenter', function() {
          zrl_mi.scroll.insideIframe = true;
          zrl_mi.scroll.scrollX = window.scrollX;
          return zrl_mi.scroll.scrollY = window.scrollY;
        });
        iframe.addEventListener('mouseleave', function() {
          return zrl_mi.scroll.insideIframe = false;
        });
      }
      return document.addEventListener('scroll', function() {
        if (zrl_mi.scroll.insideIframe) {
          return window.scrollTo(zrl_mi.scroll.scrollX, zrl_mi.scroll.scrollY);
        }
      });
    } else {
      return setTimeout(zrl_mi.add_scroll_event, 1000);
    }
  };

