/* If user has just came in, write current time in a cookie
 * and calculate time on site from the saved time in cookie
 * ToS cookie is a session cookie so it gows away as user closes the browser.
 *
 * However, if browser is open for long time, ToS is reset after timeout
 *
 * Returns ToS in miliSeconds
 */
ss_mi.helper.get_time_on_site = function(options){
  var time_on_site = 0,
    session_expiry_timeout = 12 * 60 * 60 * 1000, // 12 Hrs
    tos_cookie_name = 'ss_af_tos_' + ss_mi.partner_id;
  var browsing_start_time = ss_mi.getCookie(tos_cookie_name);
  if (browsing_start_time){
    time_on_site = (new Date).getTime() - parseInt(browsing_start_time);
    if (time_on_site > session_expiry_timeout) time_on_site = 0;
  }
  if (time_on_site == 0 || (options && options.reset)) {
    ss_mi.setCookie(tos_cookie_name, (new Date).getTime(), {path: '/'});
  }
  return time_on_site;
};

/* returns session key of a ask-a-friend session.
 * If session cookie is not already present, it genarates a random session key.
 * It also does a quick check that if cookies are enabled in the browser.
 * Hence, all ask-a-friend activity should be done only after having a non-null session key.
 */
ss_mi.helper.get_session_key = function(){
  var session_key_name = 'af_session_' + ss_mi.partner_id;
  var session_key_value = ss_mi.getCookie(session_key_name);
  if (!session_key_value){
    session_key_value = String((new Date).getTime()) + Math.round(Math.random() * 1000000);
  }
  ss_mi.setCookie(session_key_name, session_key_value, {path: '/', expires:30});
  return session_key_value;
};

ss_mi.helper.get_session_id = function(){
  var session_key_name = 'ss_session_id_' + ss_mi.partner_id;
  var session_key_value = ss_mi.getCookie(session_key_name);
  if (!session_key_value){
    session_key_value = String((new Date).getTime()) + Math.round(Math.random() * 1000000);
  }
  ss_mi.setCookie(session_key_name, session_key_value, {path: '/'});
  return session_key_value;
};

ss_mi.setStorageItem = function(name, value, options){
  if(!ss_mi.helper.localstorage_check())
    ss_mi.setCookie(name,value, options);
  if(!value || value == ''){
    try{
      localStorage.removeItem(name);
      return
    }catch(e){}
  }
  options = options || {};
  var expires = null
  if (options.expires && (typeof options.expires == 'number')){
    expires = options.expires * 24 *60 * 60 * 1000;
  }
  try{
    if(expires){
      val = JSON.stringify({'value' : value, 'expires' : expires, 'time': new Date().getTime()});
    }
    else{
      val = JSON.stringify({'value' : value, 'session_id': ss_mi.helper.get_session_id() , 'time': new Date().getTime()});
    }
    localStorage.setItem(name, val);
  }catch(e){}
};

ss_mi.getStorageItem = function(name){
  if(!ss_mi.helper.localstorage_check())
    return ss_mi.getCookie(name);
  var ret_val = null;
  try{
    val = localStorage.getItem(name);
    if(val){
      val = JSON.parse(val);
      if((val.expires && (new Date().getTime() - val.time < val.expires)) || (val.session_id && val.session_id == ss_mi.helper.get_session_id()) ){
        ret_val = val.value;
      }
      else{
        localStorage.removeItem(name);
      }
    }
  }catch(e){}
  return ret_val;
}

ss_mi.helper.localstorage_check = function(){
  try{
    localStorage.setItem('ss_test', 'ss_test');
    localStorage.removeItem('ss_test');
    return true;
  }catch(e){
    return false;
  }
}

ss_mi.helper.get_lyvisitor_id = function(){
  var ss_lyvisitor_id = ss_mi.get_url_parameter('ss_lyvisitor_id');
  if(!ss_lyvisitor_id){
    var ss_lyvisitor_id = ss_mi.getCookie('ss_lyvisitor_id');
  }
  if(ss_mi.conf.is_loyalty_enabled){
    if (!ss_lyvisitor_id){
      ss_lyvisitor_id = String((new Date).getTime()) + Math.round(Math.random() * 1000000);
    }
    ss_mi.setCookie('ss_lyvisitor_id', ss_lyvisitor_id, {path: '/'});
  }
  return ss_lyvisitor_id;
}

/* function for getting traffic source for the session.
 * Actually it is the referrer url of the landing page,
 * we shall keep that in a session cookie.
 */
ss_mi.helper.get_session_referrer = function(){
  var page_referrer = document.referrer,
    ses_ref_cookie_name = 'ss_ses_ref_' + ss_mi.partner_id;
  var session_referrer = ss_mi.getStorageItem(ses_ref_cookie_name);
  if (session_referrer === null){
    session_referrer = page_referrer;
    ss_mi.setStorageItem(ses_ref_cookie_name, session_referrer, {path: '/'});
  }
  return session_referrer;
};

/* placeholder function for reading product info from the page.
 * server will override this function by the merchant specific page parsing code.
 */
ss_mi.helper.get_product_info = function(){
  return {image_url: ss_mi.helper.get_meta_content('property', "og:image") ,
    page_url: ss_mi.helper.get_page_url(), title: ss_mi.helper.get_page_title()
  };
};

ss_mi.helper.generate_url = function(options){
  var data_str = '', url_str = '';
  if (!options) {
    alert('Please pass the necessary parameters');
    return false;
  }
  if (!options.url){
    alert('Please pass server url to call');
    return false;
  }

  /* convert data dict to url parameters string */
  if (options.data){
    if ( typeof options.data == 'object'){
      for (key in options.data){
        if (options.data[key]){
          data_str = data_str + '&' + key + '=' + encodeURIComponent(options.data[key]);
        }
      }
    } else if (typeof options.data == 'string'){
      data_str = '&' + options.data;
    }
  }
  /* get final url having url parameters string */
  url_str = (options.url.indexOf('?') >= 0) ? options.url + data_str : options.url + '?' + data_str.slice(1);
  return url_str;
};

ss_mi.helper.show_container_popup = function(container_dict){
  container_id = container_dict.container_id;
  app_type = container_dict.app_type;
  try{
    var popup = document.getElementById(container_id);
  }catch (e){
    return;
  }

  popup.style.display = "block";
  var popup_height = popup.clientHeight + 'px';
  ss_mi.helper.resize_popup(container_id)
  popup.style.height = '0px';
  popup.style.overflow = 'hidden';
  //ss_mi.effects.animate(popup, {height: popup_height}, {duration: 800}, function(){popup.style.overflow = "";});
  if(ss_mi.helper.is_mobile && container_id != 'ssmi_product_stories')
  {
    ss_mi.effects.animate(popup, {height: popup_height}, {duration: 800}, function(){popup.style.overflow = "";ss_mi.helper.resize_popup(container_id)});
    var timeoutId;
    window.addEventListener('scroll', function() {
      if(timeoutId ){
        clearTimeout(timeoutId );
      }
      timeoutId = setTimeout(function(){
        if(ss_mi.helper.is_mobile_safari){
          if(!ss_mi.is_keyboard_open){
            ss_mi.helper.resize_popup(container_id);
          }
        }
        else{
          if (!(window.innerHeight + 100 < ss_mi.window_height)) {
            ss_mi.helper.resize_popup(container_id);
            return;}
        }
      }, 100);
    });
  }
  else if (container_id == 'zrl_container' || container_id == 'zrl_raf_container')
  {
    if (zrl_mi.is_mobile){
      popup_height = '100%'
      zrl_mi.scroll.insideIframe = true;
      zrl_mi.scroll.scrollX = window.scrollX;
      zrl_mi.scroll.scrollY = window.scrollY;
    }
    popup.style.display ='none';
    popup.style.height = popup_height;
    ss_mi.conf.zindex_value = 11000;
    ss_mi.effects.fadeIn(popup);
    popup.style.overflow = "";
  }
  else
  {
    ss_mi.effects.animate(popup, {height: popup_height}, {duration: 800}, function(){popup.style.overflow = "";});
  }


  if (ss_mi.quirks_mode){
    popup.style.border = '2px solid #888';
  }else{
    if (container_id == 'zrl_raf_intermediate_div_container'){
      ss_mi.conf.zindex_value = 9999;
    }
    else if(['zrl_container','zrl_raf_container'].indexOf(container_id) >= 0){
      ss_mi.conf.zindex_value = 999999;
    }
    ss_mi.effects.add_overlay();
    if(app_type == 'get_an_email_app' && ss_mi.conf.get_an_email_app.close_app_onoverlayclick){
      if(!!document.addEventListener){
        document.getElementById('ssmi_overlay').addEventListener("click", function(){
          ss_mi.hide_product_preview(container_id, app_type);
        });
      }else{
        document.getElementById('ssmi_overlay').attachEvent("click", function(){
          ss_mi.hide_product_preview(container_id, app_type);
        });
      }
    }
  }
  try{
    var mql = window.matchMedia("(orientation: portrait)");
    mql.addListener(function(m) {
      ss_mi.helper.resize_popup(container_id);
    });
  }catch (e){}
};

ss_mi.helper.resize_popup = function(container_id){
  try{
    var popup = document.getElementById(container_id);
  }catch (e){
    return;
  }

  var win_size = ss_mi.helper.get_window_size();
  if (ss_mi.helper.is_mobile || (zrl_mi.is_mobile && container_id == 'zrl_raf_intermediate_div_container')){
    var popup_top = ss_mi.helper.get_scroll_top() + (win_size.height - popup.clientHeight)/2;
    var popup_left = ss_mi.helper.get_scroll_left() + (win_size.width - popup.clientWidth)/2;
  }else{
    var popup_top = (ss_mi.conf.popup_top) ? ss_mi.conf.popup_top : (((win_size.height - popup.clientHeight)/2) + ss_mi.conf.popup_offset);
    var popup_left = (win_size.width - popup.clientWidth)/2;
    popup.style.position = ss_mi.quirks_mode ? 'absolute': 'fixed' ;
  }
  popup_left = (popup_left > 10) ? popup_left : 10;
  popup_top = (popup_top > 10) ? popup_top : 10;
  if (zrl_mi.is_mobile && container_id != 'zrl_raf_intermediate_div_container')
  {
    popup_left = 0;
    popup_top = 0;
    popup.style.position = 'fixed';
  }
  popup.style.left = popup_left + 'px';
  popup.style.top = popup_top + 'px';

}

/* Returns The Top position of an element
 * which is passed as input parameter
 * to the function.
 * The returned value is a dict. {x: xPos, y:yPos}.
 * */
ss_mi.helper.get_element_pos = function(el){
  var lx, ly;
  lx = 0;
  ly = 0;
  while (el !== null) {
    lx += el.offsetLeft;
    ly += el.offsetTop;
    el = el.offsetParent;
  }
  return {
    x: lx,
    y: ly
  };
};

/* Checks if cookies are enabled in the browser and sets the global state
 * Apps use this info for adjusting their behavior
 *
 * */
ss_mi.helper.cookie_check = function(){
  ss_mi.setCookie('ss_cookie_check', 'cookies_enabled', {path: '/', expires:1});
  var cookies_enabled = (ss_mi.getCookie('ss_cookie_check') == 'cookies_enabled') ? true : false;
  ss_mi.setCookie('ss_cookie_check', null)
  return cookies_enabled;
};

/*
 * Checks if device is mobile
 * if Not Mobile return true
 * return true if bottombar should be displayed,
 * else false
 * used in ss_mi.hide_product_preview function
 * */
ss_mi.helper.display_sidebar_check = function (app_type)
{
  if(!ss_mi.helper.is_mobile)
  {
    if (app_type == 'real_refer_a_friend_app')
    {
      return ss_mi.conf.real_refer_a_friend_app.display_sidebar;
    }
    else
    {
      return true;
    }
  }
  else if(app_type == 'prepurchase_share_app')
  {
    return (ss_mi.conf.prepurchase_share_app.display_bottombar);
  }
  else if (app_type == 'real_refer_a_friend_app')
  {
    return (ss_mi.conf.real_refer_a_friend_app.display_bottombar);
  }
  else if (app_type == 'get_an_email_app')
  {
    return (ss_mi.conf.get_an_email_app.display_bottombar);
  }
  else if(app_type == 'purchase_share_app')
  {
    return (ss_mi.conf.purchase_share_app.display_bottombar);
  }
  return true;
}

ss_mi.effects = {
  show_top : 0,
  hide_top: 200,
  show_left : 0,
  hide_left: 200,
  popup_state : 'hide'
};

/* Sets the sidebar image and its styles for product sharing and offer sharing depending upon whether the merchant has
* its own sidebar image uploaded or using the default shopsocially image
* */
ss_mi.change_css_code = function(options){
  var sidebar, close_button;
  var popup = document.getElementById(options.id);
  sidebar = document.getElementById(options.app_div + '_image');
  close_button = document.getElementById(options.app_div + '_close_button');
  popup.style.overflow = "";
  if (sidebar && ss_mi.effects[options.app_type].popup_state == 'hide'){
    sidebar.style.display = 'block';
    //popup.style.display = 'none';
  }else{
    close_button.style.display = 'block';
    popup.style.display = 'block';
  }
};

ss_mi.effects.slide_popup = function(options){
  if(ss_mi.helper.is_mobile){return;}
  ss_mi.sync_conf(options.app_type)
  var popup = document.getElementById(options.id);
  var win_size = ss_mi.helper.get_window_size();
  popup.style.display = 'block';
  if (options.popup_offset === undefined) {
    var popup_top = Math.ceil((win_size.height - popup.clientHeight)/2 + ss_mi.conf.popup_offset);
  } else {
    var popup_top = Math.ceil((win_size.height - popup.clientHeight)/2 + options.popup_offset);
  }
  popup_top = (popup_top > 10) ? popup_top : 10;
  popup_top = (popup_top + popup.clientHeight > win_size.height) ? win_size.height - popup.clientHeight : popup_top;

  popup.style.top = popup_top + 'px';
  popup.style.position = ss_mi.quirks_mode ? 'absolute': 'fixed' ;

  if (!ss_mi.effects[options.app_type]){
    ss_mi.effects[options.app_type] = {popup_state: 'hide'};
  }
  if (options.hide){
    ss_mi.effects[options.app_type].popup_state = 'hide';
    ss_mi.change_css_code(options);
    return false;
  }

  options.slide_offset = (options.slide_offset) ? options.slide_offset : 0;

  switch (options.sidebar_placement || ss_mi.conf.sidebar_placement){
    case 'left':
    {
      ss_mi.effects.show_left = 0 ;
      ss_mi.effects.hide_left = 0 - (popup.clientWidth + 20) + options.slide_offset;
      if (ss_mi.effects[options.app_type].popup_state == 'hide'){
        ss_mi.effects.endLeft = ss_mi.effects.show_left;
        ss_mi.effects[options.app_type].popup_state = 'show';
        popup.style.left = ss_mi.effects.hide_left + 'px';
      } else if (ss_mi.effects[options.app_type].popup_state == 'show'){
        ss_mi.effects.endLeft = ss_mi.effects.hide_left;
        ss_mi.effects[options.app_type].popup_state = 'hide';
      }
      popup.style.right = '';
      popup_left = ss_mi.effects.endLeft + 'px';
      ss_mi.effects.animate(popup,{left:popup_left}, {duration: 400}, function(){ss_mi.change_css_code(options);});
      break;
    }
    case 'right':
    {
      ss_mi.effects.show_right = 0;
      ss_mi.effects.hide_right = 0 - (popup.clientWidth + 20) + options.slide_offset;
      if (ss_mi.effects[options.app_type].popup_state == 'hide'){
        ss_mi.effects.endRight = ss_mi.effects.show_right;
        ss_mi.effects[options.app_type].popup_state = 'show';
        popup.style.right = ss_mi.effects.hide_right + 'px';
      } else if (ss_mi.effects[options.app_type].popup_state == 'show'){
        ss_mi.effects.endRight = ss_mi.effects.hide_right;
        ss_mi.effects[options.app_type].popup_state = 'hide';
      }
      popup.style.left = '';
      popup_right = ss_mi.effects.endRight + 'px';
      ss_mi.effects.animate(popup,{right:popup_right}, {duration: 400}, function(){ss_mi.change_css_code(options);});
      break;
    }
  }


};


