ss_mi.effects.add_overlay = function(data){
  if(!data){data = {};}
  var e = document.createElement('div');
  e.setAttribute("id", "ssmi_overlay");
  var f = document.createElement('div');
  e.appendChild(f);
  e.style.zIndex = ss_mi.conf.zindex_value - 1;
  e.style.left = '0px';
  e.style.top = '0px';
  e.style.height = '100%';
  e.style.width = '100%';
  e.style.position = 'fixed';
  e.style.backgroundColor = '#000';
  e.style.opacity = '0.3';
  e.style.filter = 'alpha(opacity=30)';
  if(data.id){
    var b = document.getElementById(data.id);
  }else{
    var b = document.getElementsByTagName("body").item(0);
  }
  b.appendChild(e);
};

ss_mi.effects.remove_overlay = function(){
  try{
    var o = document.getElementById("ssmi_overlay");
    var p = document.getElementById("ssmi_overlay").parentNode;
    p.removeChild(o);
  }catch(e){

  }
};

/*Expects the elem to have display:none */
ss_mi.effects.fadeIn =function (elem) {
  var o = 0;
  var timer = setInterval(function () {
    if (o >= 1.0) {
      clearInterval(timer);
    }
    elem.style.opacity = o;
    elem.style.filter = 'alpha(opacity=' + o * 100 + ")";
    o += 0.01;
    if(o > 0){
      elem.style.display = 'block';
    }
  }, 5);
};

ss_mi.effects.fadeOut = function (elem) {
  var o = 1;
  var timer = setInterval(function () {
    if (o <= 0.0) {
      clearInterval(timer);
    }
    elem.style.opacity = o;
    elem.style.filter = 'alpha(opacity=' + o * 100 + ")";
    o -= 0.01;
    if(o < 0.01)
    {
      elem.style.display = 'none';
    }
  }, 5);
};

ss_mi.effects.fadeToggle = function(elem){
  var o = elem.style.opacity;
  if (o <= 0.01)
  {
    ss_mi.effects.fadeIn(elem);
  }
  else
  {
    ss_mi.effects.fadeOut(elem);
  }
};

ss_mi.setCookie = function(name, value, options) {
  options = options || {};
  if (value === null || value === '') {
    value = '';
    options.expires = -1;
  }
  if (!options.domain && ss_mi.conf.base_domain){
    options.domain = ss_mi.conf.base_domain;
  }
  var expires = '';
  if (options.expires && (typeof options.expires == 'number' || options.expires.toUTCString)) {
    var date;
    if (typeof options.expires == 'number') {
      date = new Date();
      date.setTime(date.getTime() + (options.expires * 24 * 60 * 60 * 1000));
    } else {
      date = options.expires;
    }
    expires = '; expires=' + date.toUTCString(); // use expires attribute, max-age is not supported by IE
  }
  // CAUTION: Needed to parenthesize options.path and options.domain
  // in the following expressions, otherwise they evaluate to undefined
  // in the packed version for some reason...
  var path = options.path ? '; path=' + (options.path) : '; path=/';
  var domain = options.domain ? '; domain=' + (options.domain) : '';
  var secure = '; secure';
  var samesite = '; samesite=none';
  if (document.location.protocol==="https:") {
    document.cookie = [name, '=', encodeURIComponent(value), expires, path, domain, secure, samesite].join('');
  }
  else {
    document.cookie = [name, '=', encodeURIComponent(value), expires, path, domain].join('');
  }
};
ss_mi.getCookie = function(name) { // only name given, get cookie
  var cookieValue = null;
  if (document.cookie && document.cookie != '') {
    var cookies = document.cookie.split(';');
    for (var i = 0; i < cookies.length; i++) {
      var cookie = ss_mi.trim(cookies[i]);
      // Does this cookie string begin with the name we want?
      if (cookie.substring(0, name.length + 1) == (name + '=')) {
        cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
        break;
      }
    }
  }
  return cookieValue;
};

ss_mi.trim = function(str) {
  return str.replace(/^\s+|\s+$/g,"");
};

var mpq = [];

// emile.js (c) 2009 Thomas Fuchs
// Licensed under the terms of the MIT license.

(function(emile, container){
  var parseEl = document.createElement('div'),
    props = ('backgroundColor borderBottomColor borderBottomWidth borderLeftColor borderLeftWidth '+
      'borderRightColor borderRightWidth borderSpacing borderTopColor borderTopWidth bottom color fontSize '+
      'fontWeight height left letterSpacing lineHeight marginBottom marginLeft marginRight marginTop maxHeight '+
      'maxWidth minHeight minWidth opacity outlineColor outlineOffset outlineWidth paddingBottom paddingLeft '+
      'paddingRight paddingTop right textIndent top width wordSpacing zIndex').split(' ');

  function interpolate(source,target,pos){ return (source+(target-source)*pos).toFixed(3); }
  function s(str, p, c){ return str.substr(p,c||1); }
  function color(source,target,pos){
    var i = 2, j, c, tmp, v = [], r = [];
    while(j=3,c=arguments[i-1],i--)
      if(s(c,0)=='r') { c = c.match(/\d+/g); while(j--) v.push(~~c[j]); } else {
        if(c.length==4) c='#'+s(c,1)+s(c,1)+s(c,2)+s(c,2)+s(c,3)+s(c,3);
        while(j--) v.push(parseInt(s(c,1+j*2,2), 16)); }
    while(j--) { tmp = ~~(v[j+3]+(v[j]-v[j+3])*pos); r.push(tmp<0?0:tmp>255?255:tmp); }
    return 'rgb('+r.join(',')+')';
  }

  function parse(prop){
    var p = parseFloat(prop), q = prop.replace(/^[\-\d\.]+/,'');
    return isNaN(p) ? { v: q, f: color, u: ''} : { v: p, f: interpolate, u: q };
  }

  function normalize(style){
    var css, rules = {}, i = props.length, v;
    //parseEl.innerHTML = '<div style="'+style+'"></div>';
    //css = parseEl.childNodes[0].style;
    css = style;
    while(i--) if(v = css[props[i]]) rules[props[i]] = parse(v);
    return rules;
  }

  container[emile] = function(el, style, opts, after){
    el = typeof el == 'string' ? document.getElementById(el) : el;
    opts = opts || {};
    var target = normalize(style), comp = el.currentStyle ? el.currentStyle : getComputedStyle(el, null),
      prop, current = {}, start = +new Date, dur = opts.duration||200, finish = start+dur, interval,
      easing = opts.easing || function(pos){ return (-Math.cos(pos*Math.PI)/2) + 0.5; };
    for(prop in target) current[prop] = parse(comp[prop]);
    interval = setInterval(function(){
      var time = +new Date, pos = time>finish ? 1 : (time-start)/dur;
      for(prop in target)
        el.style[prop] = target[prop].f(current[prop].v,target[prop].v,easing(pos)) + target[prop].u;
      if(time>finish) { clearInterval(interval); opts.after && opts.after(); after && setTimeout(after,1); }
    },10);
  }
})('animate', ss_mi.effects);

ss_mi.dispatch_function = function(data){
  if (data[0] == 'init'){
    ss_mi.init(data[1]);
  }
  else if (data[0] == 'products'){
    ss_mi.add_products(data[1]);
  }
};

ss_mi.init_ssly = function(){
  if (typeof _ssq === 'undefined'){
    //do nothing DOM ready is already done so returning is also a safe option
    temp_q = [];
  }else{
    temp_q = _ssq;
  }
  _ssq = {};
  _ssq.push = function(data){
    if (typeof data === 'object' && data.length == 2){
      ss_mi.dispatch_function(data);
    }else{
      return false;
    }
  };
  while(temp_q.length > 0){
    _ssq.push(temp_q.pop());
  }
};

