zrl_mi.dispatch_function = function(data){
  if (data[0] == 'init') {
    if (data[1]?.version == "v2") {
      zrl_mi.init_member_auth_v2(data[1])
    }
    else {
      zrl_mi.init(data[1]);
    }
  }
  else if (data[0] == 'track_order') {
    zrl_mi.track_order(data[1]);
  }
};


zrl_mi.init_zrl = function(){
  if (typeof _zrl === 'undefined'){
    temp_q = [];
  } else {
    temp_q = _zrl;
  }
  _zrl = {};
  _zrl.push = function(data) {
    if (typeof data === 'object' && data.length == 2) {
      zrl_mi.dispatch_function(data);
    } else {
      return false;
    }
  };
  while(temp_q.length > 0){
    _zrl.push(temp_q.pop());
  }
};

zrl_mi.init_zrl();

